  doc.tables.splice(3,0,{"id":"cleaning","title":"房间打扫配置 MotelRoomCleaning","desc":"每房间解锁前一次点击交互与动画表现，不新增工具、额外关卡、收费或奖励。资源由后续美术提供。","columns":["英文字段名","中文名称","类型／结构","使用说明"],"rows":[["cleaning_rule_id","打扫规则ID","int，唯一","供房间cleaning_rule_id引用。"],["room_id","关联房间ID","int → MotelRoom","一房间的打扫完成记录独立，不等于区域整体开放。"],["dirty_scene_resource","打扫前外观","资源key","该房间未整理时的场景。"],["clean_scene_resource","打扫后外观","资源key","完成表演后展示的房间基底；正式家具初始布局仍按房间／点位配置。"],["animation_resource","点击打扫表演","资源key","点房间区域触发的交互与动画，不加入擦拭、工具或点击次数指标。"],["complete_event_key","表演完成事件","事件key","与完成记录衔接；重复点击／回调不能重复完成或发额外奖励。"]]});
  for (const args of [["home",6,1,"房间进入与打扫","按房间开放状态处理点击：未达原有开放条件时不越过条件进入；进入解锁前打扫阶段时，点击该房间区域触发一次打扫交互和动画，完成后展示整理好的房间。已完成打扫的已开放房间点击后拉近并进入房间总览。"],["home",5,1,"刷新","家具激活、升级或套装等级提升成功后，若影响该累计数值，读取最新结果；获得材料本身不等于激活。装修、换下家具及同家具跨房间摆放均不重复加数值。"],["decorate",1,1,"切换放弃当前预览","点击其他房间时放弃当前房间未保存的预览，不自动保存。目标房间从其自己的正式布局开始；不会把当前预览带到别的房间。"],["decorate",3,0,"候选与同房间唯一","按当前房间及点位白名单过滤，只允许已激活家具用于装修。同一家具在同房间只能摆一处，其他点位已使用时不可重复装配；可以在其他合规房间同时使用，不额外耗材料。未激活家具是否保留置灰卡面仍待确认。"],["decorate",3,1,"点击预览","点击只改变当前点位预览，不保存就不改变正式布局。星级与家具等级分开；摆放不产生属性加成，换下也不撤销已激活加成。"],["decorate",5,0,"只保存当前房间","提交并校验当前房间的点位适配、激活资格及同家具不可重复；成功更新本房间正式布局，并更新本房间修改前基准，不影响其他房间。失败不更新正式布局。"],["decorate",5,1,"保存范围","仅保存当前房间。其他房间未保存预览会在切换时放弃，不存在此按钮批量保存全部房间的行为。"],["decorate",6,0,"恢复本次修改前布局","圆箭头恢复玩家这次开始改动当前房间前的基准布局，不是恢复配置中的初始家具，也不是只撤销最近一步。若中途保存成功，以最近保存成功的布局作为新的修改前基准。"],["decorate",7,0,"未保存返回提示","未保存修改时点击返回，弹出放弃修改提示。取消则回到当前预览继续修改；确认才放弃并返回。没有未保存修改时正常返回。提示界面截图待补，不使用未经确认的其他系统截图。"],["set-list",3,0,"按获得统计总进度","分子统计永久已获得记录中的不同家具ID，分母取图鉴配置范围；不要求激活，不按当前库存计数。重复获得只增加材料，激活／升级消耗材料不会降低已收集数量。图鉴是否包含隐藏／未投放家具的总范围仍待配置。"],["set-list",4,1,"套装收集数据","套装成员总数来自配置；收集分子为本套已获得家具ID去重数，未激活但已获得也计入。此进度与“全员达到下一等级”的套装成长进度分开。排序和红点细节待确认。"],["set-list",5,0,"奖励独立领取","奖励领取与套装等级提升分开。已达到对应套装等级且该级奖励未领取时可领，成功后记录该级已领取；提升套装不会自动发奖，提升更高等级也不清除低等级未领取奖励。礼物入口的多级奖励展开图仍待补。"],["single-list",3,0,"按获得统计进度","收集统计与套装页同源：已获得不要求激活，未激活不等于未获得；重复材料和库存消耗都不重复增加或减少收集种类。"],["single-list",5,0,"获得、激活与等级分别显示","卡面是否获得看永久获得记录，不看是否激活或库存是否为0。已获得未激活不能贴未获得标记；已激活且库存0也不能显示未获得。固定星级与当前等级分开；红点细则待确认。"],["direct-shop",4,0,"每日自动刷新","当天首次进入生成／呈现当日货架，之后正常重进沿用当前批次；自动刷新不占用当天首次手动免费次数。具体每日刷新时点待配。"],["direct-shop",4,1,"每日一次免费，之后付费整批刷新","当天首次手动刷新免费，第2次起按配置道具ID和数量扣除；刷新成功将所有格子整批替换，不保留未购或售罄商品。新一批可以和上一批抽到相同家具，但同屏家具不得重复。材料不足或失败不扣费、不换货架、不增加成功刷新次数。"],["direct-shop",5,0,"当前货架显示","展示当批家具、名称、固定星级、数量与价格；按家具ID同屏去重。每格购买一次后显示售罄，保留该格原商品直至整批刷新，不在购买后自动补货。"],["direct-shop",5,1,"每格限购一次","按当前货架批次和格子提交购买；扣款、发材料及记录该格已购买一并成功后显示售罄。重复点击不再次扣发；同家具在其他房间是否开放不影响已确认的盲盒可获得规则，直购商品资格仍按已配商品池。"],["direct-shop",5,2,"整批刷新与跨批重复","刷新产生新批次，全部格子的售罄状态随旧批次结束，新格可各买一次；旧批次购买请求要校验批次，不用旧价格扣到新商品。新一批允许与上一批有相同家具，不存在锁定／保留商品。"]]) entry(...args);
  for(const sid of ['set-detail-activate','set-detail-upgrade']) for(const args of [[2,0,"成员卡片","右侧展示本套全部成员，是否获得、是否激活和当前等级分别读取。未激活不等于未获得，库存为0也不意味着未获得。切换卡片只切换查看对象。"],[2,1,"材料与成长","已获得家具进入收集进度，但须手动激活才有属性和装修资格；激活后按等级配置消耗重复材料成长。卡片是否可操作看当前库存和等级，不反向修改获得状态。"],[4,1,"状态切换","未获得显示获取途径；已获得未激活显示激活，并单独检查所需材料；已激活显示升级，即使库存不足仍保持已激活。满级展示方式待确认。"],[5,0,"两种进度分开","套装收集进度统计本套已获得家具种类，未激活也计入；套装成长达标进度统计全员中达到目标家具等级的成员。套装当前等级、效果与奖励状态分别显示，不混用一个进度数。"],[6,0,"套装手动提升，奖励另行领取","全套成员均已激活且家具等级达到N级后，才可手动提升套装至N级。提升只更新套装等级和对应效果，不自动发放该级奖励；奖励另点领取，每级只领一次，未领低级奖励不会因继续提升而消失。套装等级上限和奖励入口具体表现待配置／补图。"]]) entry(sid,...args);
