  screen("decorate").uiRules.find(x=>x.id===7).rules[0].popup={"id":"motel-discard-preview","kind":"popup","title":"放弃未保存修改提示","summary":"用户确认未保存返回需提示；界面截图待补。恢复与切换规则已明确，不用未确认的其他系统图片替代。","image":"","hotspots":[],"rules":[{"label":"触发条件","text":"当前房间预览与本次修改前基准不同时点击返回，先提示是否放弃未保存修改；无修改时不弹。"},{"label":"取消","text":"关闭提示，留在当前房间装修预览，保留未保存修改。"},{"label":"确认放弃","text":"丢弃本房间未保存预览，返回上一界面；不回滚已成功的家具获取、激活或升级。"},{"label":"界面待补","text":"用户尚未提供该提示截图；按钮位置与正式文案随确认截图补齐。"}]};
