  furniturePopup.rules[2]={label:"3.激活",text:"已获得未激活时显示激活，另检查当前材料是否够1件；成功扣1件并永久解锁装修与属性，材料不足不激活。激活耗尽库存后仍为已获得、已激活，不自动摆进房间。"};
  furniturePopup.rules[3]={label:"4.升级",text:"已激活未满级时显示升级，展示当前／下级效果和所需材料。即使当前库存0仍是已激活状态，只是升级材料不足；满级文案待确认。"};
  furniturePopup.rules[5]={label:"6.激活加成与摆放无关",text:"用户确认加成只与激活及其后等级成长有关。已激活未摆放也生效；换下家具不掉加成，同家具摆多个房间不重复加成。"};
// 旅馆事件：按用户新增范围补内容配置，不改现有装修／家具规则。
  rule("scope",1,"本次内容","本次包含每个房间解锁前的一次点击打扫交互与动画、区域与房间浏览、固定点位装修、套装／散件图鉴、手动激活和升级、家具商城（盲盒＋直购），以及NPC气泡入口、对话／行为选项和小资源奖励组成的旅馆事件。");
  const eventIndex=doc.sections.findIndex(s=>s[0]==="pending");
  doc.sections.splice(eventIndex,0,["events","旅馆事件与内容配表",[["定位与入口","本版加入旅馆事件，用于处理客人请求、NPC冲突等轻量互动，增强旅馆沉浸感。场景内NPC头顶出现气泡，点击NPC／气泡进入对话；可选择回答或行为，并得到对应结果。不扩为住客养成或客房经营。"],["配置关系","事件主表 → 起始对话节点 → 回答／行为选项 → 后续对话／结尾。台词和选项通过多语言key配置，NPC和行为表演使用资源及程序预置行为ID。回答可分支，行为完成后可接不同结果台词。"],["小资源奖励","不同结尾可配置不同奖励组，具体资源与数量待配。奖励统一归结尾节点，进入结算时检查同一事件实例是否已经发过，避免反复点气泡、选项或断线重试重复给资源。未确认的收费、失败惩罚或额外养成不加入。"],["触发节奏与界面边界","本次先补事件内容配置。可出现条件、触发时机、重复次数、冷却、同时存在数量和中途关闭后的恢复规则仍待确认，不自行拍定每日数量。气泡／对话窗口尚无确认截图，先不扩写新界面分页或凭空叠标号；后续有图再补。"],["分支写法示例（非正式投放）","例如“客人反映隔壁吵闹”：NPC提出问题 → 选“先了解情况”进入补充台词；选“前去协调”调用预置行为 → 进入处理结果结尾，按该结尾奖励组结算。此例只演示表间关系，不作为已定剧情、动作或资源数值。"]]]);
  doc.tables.push(...[{"id":"event-main","title":"旅馆事件主表 MotelEvent","desc":"配置一个旅馆事件的身份、NPC入口、位置、气泡与起始对话。触发节奏和具体事件内容待填，不预设每天几个或固定几分钟刷新。","columns":["英文字段名","中文名称","类型／结构","使用说明"],"rows":[["event_id","事件ID","int，唯一","同一个完整事件的标识，关联所有对话节点；不使用台词或NPC名字当存档键。"],["name_key","事件名称","多语言key","例如处理客人请求、协调冲突；名称和文案由事件内容配置，不作为新增住客经营系统。"],["area_id","事件所在区域","int → 旅馆区域表","指定本馆、前场或后院中的场景，使用现有区域ID。"],["room_id","事件所在房间","int → 房间表；null=区域场景","指定房间内事件；区域事件明确填null，不把未填写当作任意房间。"],["npc_id","入口NPC ID","int → NPC资源／角色配置","显示在场景中且头顶带气泡的NPC。对话可由其他NPC或玩家发言，由节点speaker_id指定。"],["anchor_key","NPC出现位置","场景资源锚点key","指定NPC在当前场景中的位置；不是新增一个家具固定点位，也不占家具装配位置。"],["bubble_text_key","头顶气泡提示","多语言key","有该事件时展示的短提示；玩家点击NPC／气泡进入本事件起始对话。气泡具体界面表现待补图。"],["start_node_id","起始对话节点ID","int → 事件对话节点表","必须属于本event_id，点击入口后从此节点开始本次交互。"],["trigger_rule","生成与重复规则","结构：condition_id、trigger_timing、repeat_limit、cooldown_seconds","condition_id为可出现条件；trigger_timing为触发时机；repeat_limit为重复次数限制；cooldown_seconds为冷却秒数。字段结构预留，具体时机、次数、冷却未确认，不自行填成每天刷新或无限重复。"]]},{"id":"event-node","title":"旅馆事件对话节点表 MotelEventNode","desc":"一个事件由多个节点组成。节点可只说一句话、给选项，或作为结尾。回答和行为可以走不同分支，奖励统一放在结尾节点，避免主表、节点、选项各发一次。","columns":["英文字段名","中文名称","类型／结构","使用说明"],"rows":[["node_id","对话节点ID","int，唯一","选项及起始节点通过此ID引用。"],["event_id","所属事件ID","int → MotelEvent","一个节点属于一个事件；普通分支不得跳到其他事件的节点。"],["speaker_id","说话者ID","角色／NPC ID；玩家使用约定标识","决定当前是谁说话，可在入口NPC、其他NPC和玩家之间切换；玩家标识由工程统一，不在本稿虚构实际ID。"],["dialogue_key","对话内容","多语言key","配置当前节点台词。可用于询问需求、回应选择、反馈处理结果。"],["option_ids","可选项ID组","int[] → 事件选项表","按数组顺序显示选项；每个选项关联当前节点。没有选项填空数组[]。"],["next_node_id","无选项时的后续节点","int → 本事件节点；null=无","用于普通对话继续推进。有option_ids时通过选项跳转，本字段填null，不能同时走两条后续。"],["is_end","是否事件结尾","bool","true表示本条为结尾，option_ids必须为空且next_node_id为null；false表示还会继续对话／选择。"],["reward_group_id","结尾奖励组ID","int → 奖励表；null=无奖励","只在is_end=true的结尾配置。可由不同分支到不同结尾，给予各自的小资源；具体道具与数量待配，不复用家具套装领奖状态。"]]},{"id":"event-option","title":"旅馆事件选项表 MotelEventOption","desc":"回答选项负责回应台词，行为选项负责调用程序已实现的事件行为，再转到结果节点。不把内容配置当可执行脚本，也不因此加入新小游戏。","columns":["英文字段名","中文名称","类型／结构","使用说明"],"rows":[["option_id","选项ID","int，唯一","用于记录玩家本次选择，供节点option_ids引用。"],["node_id","所属对话节点ID","int → MotelEventNode","限定本选项出现在哪个节点；顺序取该节点的option_ids顺序。"],["text_key","选项显示文本","多语言key","玩家看到的回答或行为说明，例如“先了解情况”“前去协调”；仅为写法示例，非正式事件文案。"],["option_type","选项类型","int：1=回答；2=行为","1通过所选回答跳转后续台词；2执行action_id指定的预置行为后，进入后续节点。"],["next_node_id","选择后节点ID","int → 同事件节点","可指向普通对话或结尾节点，不用按钮文字判断分支。行为失败／未完成时不得直接跳到成功领奖结尾。"],["action_id","预置行为ID","int → 程序预置事件行为；回答类型填null","仅行为选项使用，例如程序已实现的NPC表演／交互。行为具体清单后续按内容定，不允许在这里写任意脚本。"],["action_params","行为参数","按action_id定义的参数对象；回答类型填null","可传参与NPC、动画资源、交互目标等已约定参数；不同action_id各自说明参数含义，不能只写一段无法解析的中文让程序猜。"],["condition_id","选项可用条件ID","int → 通用条件表；null=无附加条件","用于条件选项；条件不满足时是隐藏还是置灰，按unavailable_mode处理。不自行增加扣费或额外材料需求。"],["unavailable_mode","条件不满足时显示方式","int：1=隐藏；2=置灰不可选","只在配置condition_id时使用；无附加条件的选项不因未配此项被锁定。"]]}]);
  addRow("player","motel_event_records","旅馆事件实例与结算记录","按event_instance_id保存event_id、current_node_id、chosen_option_ids、completed、reward_receipt","区分事件配置与当次出现实例；记录选项和完成结果，已结算实例不能重复发奖。中断恢复方式随最终事件触发规则确认。");
  addRule("accept","旅馆事件内容检查","事件起始节点、选项和后续节点须存在且属于同一事件；非结尾不得配结尾奖励；有选项时不能再走无选项后续；行为必须为程序已实现行为，失败不能直接跳成功结尾；同一事件实例的奖励不重复结算。");
  addRule("pending","旅馆事件待补","事件实际触发时机、次数／冷却、同时存在数量、中断恢复规则、正式台词、行为表演及奖励道具数量待补；NPC气泡和对话选项界面待图。本稿只完成事件内容配表，不将这些参数默认成每日固定刷新。");
  section("scope")[2]=section("scope")[2].filter(item=>item[0]!=="资料优先级");
